<template>
  <div class="exhibition-walk-pad">
    <button ref="pad" type="button" aria-label="Walk around the exhibition" @pointerdown="start" @pointermove="move" @pointerup="finish" @pointercancel="finish" @lostpointercapture="finish" @contextmenu.prevent>
      <svg viewBox="0 0 72 72" aria-hidden="true"><circle cx="36" cy="36" r="32"/><path d="m33 11 3-3 3 3m-6 50 3 3 3-3M11 33l-3 3 3 3m50-6 3 3-3 3"/></svg>
      <span :style="{ transform: `translate(${x * 23}px, ${y * 23}px)` }"></span>
    </button>
    <small aria-hidden="true">Walk</small>
  </div>
</template>
<script>
export default {
  emits: ['move'],
  data: () => ({ x: 0, y: 0 }),
  mounted() { window.addEventListener('blur', this.finish); document.addEventListener('visibilitychange', this.finish); },
  beforeUnmount() { this.finish(); window.removeEventListener('blur', this.finish); document.removeEventListener('visibilitychange', this.finish); },
  methods: {
    start(event) {
      if (event.button !== 0) return;
      event.preventDefault(); this._pointer = event.pointerId;
      this._rect = this.$refs.pad.getBoundingClientRect();
      this.$refs.pad.setPointerCapture(event.pointerId); this.move(event);
    },
    move(event) {
      if (event.pointerId !== this._pointer) return;
      const dx = (event.clientX - this._rect.left - this._rect.width / 2) / 23;
      const dy = (event.clientY - this._rect.top - this._rect.height / 2) / 23;
      const length = Math.max(1, Math.hypot(dx, dy));
      this.x = dx / length; this.y = dy / length;
      this.$emit('move', { x: Math.abs(this.x) < .12 ? 0 : this.x, y: Math.abs(this.y) < .12 ? 0 : this.y });
    },
    finish() {
      const id = this._pointer; this._pointer = null;
      this.x = 0; this.y = 0; this.$emit('move', { x: 0, y: 0 });
      if (id != null && this.$refs.pad?.hasPointerCapture(id)) this.$refs.pad.releasePointerCapture(id);
    },
  },
};
</script>
<style scoped>
.exhibition-walk-pad { width: 72px; text-align: center; color: var(--ex-muted); }
button { position: relative; width: 72px; height: 72px; padding: 0; border: 0; border-radius: 50%; background: color-mix(in srgb, var(--ex-paper) 60%, transparent); color: inherit; touch-action: none; user-select: none; -webkit-user-select: none; }
button:focus-visible { outline: 1px solid currentColor; outline-offset: 3px; }
svg { width: 100%; height: 100%; fill: none; stroke: currentColor; stroke-width: .75; opacity: .55; }
button span { position: absolute; top: 27px; left: 27px; width: 18px; height: 18px; background: currentColor; opacity: .7; border-radius: 50%; pointer-events: none; }
small { display: block; font: 10px/1.4 'Quattrocento Sans', sans-serif; margin-top: 3px; }
</style>
